-- ============================================================
-- 035_reading_passages_backfill.sql
-- Populates reading_passages for the 5 existing IELTS Reading
-- practice tests (030_ielts_reading_practice_tests.sql), and tags
-- each of their questions with which passage it belongs to (via
-- questions.metadata, merging in alongside any existing metadata
-- such as a matching question's pairs) -- both needed for the
-- split-screen "CD test" practice UI.
-- ============================================================

do $$
declare
  v_lesson uuid;
  v_qset uuid;
begin
  -- Test 1
  select id into v_lesson from lessons where slug = 'test-1' and node_id = (select cn.id from content_nodes cn join content_nodes reading on cn.parent_id = reading.id join content_nodes ielts on reading.parent_id = ielts.id where ielts.slug = 'ielts' and reading.slug = 'reading' and cn.slug = 'practice-tests');
  select id into v_qset from question_sets where lesson_id = v_lesson;

  insert into reading_passages (lesson_id, passage_number, title, paragraphs) values (v_lesson, 1, 'The Story of Chocolate', '[{"label":null,"text":"Long before chocolate became the sweet confectionery enjoyed around the world today, it began as a bitter beverage consumed by the early civilisations of Mesoamerica. The cacao tree, from which all chocolate is ultimately derived, is native to the tropical regions of Central and South America. Archaeological evidence suggests that the Olmec, one of the earliest civilisations to flourish in the region, were consuming cacao in some form as far back as 1500 BCE, though they left no written records explaining exactly how it was prepared."},{"label":null,"text":"The practice was later adopted and elaborated upon by the Maya and, subsequently, the Aztec civilisations, both of whom held cacao in extremely high regard. Cacao beans were mixed with water, chilli peppers and other spices to produce a frothy, bitter drink that was far removed from the sweet treat familiar today. Among the Aztecs, cacao beans became so highly valued that they were used as a form of currency, and the drink itself was largely reserved for nobles, priests and warriors rather than ordinary citizens."},{"label":null,"text":"Cacao first reached Europe in the sixteenth century, following the Spanish conquest of Mesoamerica. Spanish colonists and missionaries began exporting cacao beans back to Spain, where the drink was gradually transformed to suit European tastes. Sugar and, later, vanilla were added to counteract the natural bitterness, and the resulting sweetened beverage quickly became a fashionable, if expensive, drink among the European aristocracy. For roughly a century, Spain managed to keep the recipe largely secret from the rest of the continent, but by the 1600s knowledge of chocolate had spread to France, Italy and England."},{"label":null,"text":"The transformation of chocolate from an exclusive drink into an affordable, solid confection depended on a series of technical innovations during the nineteenth century. In 1828, a Dutch chemist developed a hydraulic press capable of separating cocoa butter from roasted, ground cacao beans, leaving behind a fine powder that could be mixed with liquids far more easily than before. This innovation also produced surplus cocoa butter, which manufacturers later combined with cocoa powder and sugar to create the first solid chocolate bars in England in the 1840s."},{"label":null,"text":"Milk chocolate, now the most widely consumed variety in many countries, was not developed until several decades later, when a Swiss manufacturer discovered a method of blending condensed milk with chocolate liquor to produce a smoother, creamier product. By the early twentieth century, industrial manufacturing techniques had made chocolate affordable enough for mass consumption, and it rapidly evolved from a luxury item into an everyday product sold in shops across the world."},{"label":null,"text":"Today, cacao cultivation has shifted dramatically away from its original home in the Americas. The majority of the world’s cacao is now grown in West Africa, particularly in Ivory Coast and Ghana, which together supply well over half of global production. This shift has brought its own set of challenges, including persistent concerns about labour practices on some cacao farms, which have prompted the growth of certification schemes intended to guarantee fairer conditions and prices for farmers."}]'::jsonb);
  insert into reading_passages (lesson_id, passage_number, title, paragraphs) values (v_lesson, 2, 'Circadian Rhythms and the Science of Sleep', '[{"label":"Paragraph A","text":"Nearly every living organism, from single-celled algae to human beings, possesses an internal biological clock that follows a roughly 24-hour cycle. This clock, known as the circadian rhythm — from the Latin circa diem, meaning “about a day” — governs far more than simply when we feel sleepy. It regulates body temperature, hormone release, appetite and even the timing of cell repair, quietly shaping the rhythm of daily life in ways most people never consciously notice."},{"label":"Paragraph B","text":"It was not until the 1970s that scientists identified the precise location of this internal clock: a small cluster of neurons in the hypothalamus known as the suprachiasmatic nucleus, or SCN. The SCN receives information directly from the retina, allowing it to detect changes in light and dark. Light is the primary external cue, known as a zeitgeber, that resets the clock each day, which explains why exposure to daylight in the morning is so effective at correcting a disrupted sleep schedule."},{"label":"Paragraph C","text":"One of the clock’s most important outputs is melatonin, a hormone produced by the pineal gland in response to darkness. As light fades in the evening, melatonin levels rise, signalling to the body that it is time to prepare for sleep. Unfortunately, artificial light — particularly the blue light emitted by phones, tablets and computer screens — can suppress melatonin production, tricking the brain into believing it is still daytime and delaying the onset of sleep, sometimes by an hour or more."},{"label":"Paragraph D","text":"Not everyone’s clock runs on exactly the same schedule. Individual variation in circadian timing gives rise to what researchers call chronotypes, popularly described as “larks”, who wake and feel most alert early in the day, and “owls”, who naturally function better later in the evening. These preferences appear to be substantially influenced by genetics. Notably, adolescents undergo a temporary shift towards a later chronotype during puberty, which places them at odds with early school start times — a mismatch that some researchers argue contributes to widespread sleep deprivation among teenagers."},{"label":"Paragraph E","text":"Chronic disruption of the circadian rhythm, whether through shift work, frequent long-haul travel or simply irregular sleep habits, has been linked to a range of health problems. These include impaired concentration and memory, a weakened immune response, and an increased risk of cardiovascular disease and metabolic disorders such as type 2 diabetes. Shift workers, whose sleep schedules are frequently misaligned with natural light patterns, appear to be at particularly elevated risk."},{"label":"Paragraph F","text":"In response to this growing body of evidence, a number of practical interventions have emerged. Controlled light therapy is now commonly used to treat jet lag and seasonal affective disorder, while some workplaces have introduced carefully scheduled light exposure for night-shift employees. Perhaps most notably, chronobiology research has fuelled growing calls for schools to delay their start times, on the grounds that doing so would better align the school day with adolescents’ natural sleep patterns — a policy change that a small but increasing number of institutions have begun to adopt."}]'::jsonb);
  insert into reading_passages (lesson_id, passage_number, title, paragraphs) values (v_lesson, 3, 'Artificial Intelligence in Everyday Life', '[{"label":null,"text":"Artificial intelligence, once confined largely to research laboratories, is now woven into the fabric of daily life. Recommendation algorithms decide which films appear at the top of a streaming service, voice assistants answer spoken questions, navigation apps predict traffic in real time, and spam filters quietly sort unwanted email before it ever reaches an inbox. Most people interact with some form of AI system dozens of times a day, often without any awareness that they are doing so."},{"label":null,"text":"Much of this is powered by machine learning, a branch of AI in which systems improve their performance through exposure to large volumes of data rather than through being explicitly programmed for every possible scenario. This approach enables remarkable personalisation, but it also raises a well-known difficulty sometimes referred to as the black box problem: the process by which certain AI systems reach a specific decision can be so complex that even the engineers who built the system cannot always fully explain a particular output."},{"label":null,"text":"Some critics have called for AI to be banned outright from sensitive areas such as hiring decisions or loan approvals. This position, in my view, overstates the case. The underlying problem is not artificial intelligence itself, but a lack of adequate regulation and transparency requirements. When properly regulated and audited, algorithmic decision-making has the potential to reduce human bias rather than amplify it, since a well-designed algorithm does not tire, does not hold conscious prejudice, and applies the same criteria consistently to every case. That said, algorithms are not inherently neutral: they can inherit and even reinforce biases present in their training data if that data reflects historical inequalities."},{"label":null,"text":"The effect of AI on employment remains a particularly contentious question. Certain categories of work, such as routine data entry and basic customer service, have already been partly displaced by automated systems. At the same time, entirely new roles have emerged, including AI trainers, algorithmic auditors and AI ethics specialists. Despite confident predictions from commentators on both sides, economists remain genuinely divided, and the net long-term effect on overall employment is, at present, impossible to state with any real certainty."},{"label":null,"text":"Looking ahead, AI is likely to become further embedded in healthcare, where it already assists in diagnostic imaging, and in education, where adaptive tutoring systems can personalise instruction to an individual student’s pace. Autonomous vehicles, too, continue to move gradually towards wider deployment. Yet public trust in these technologies will ultimately depend on demonstrated reliability and clear accountability when systems fail, not merely on technical capability. A self-driving car that performs perfectly ninety-nine times out of a hundred will not earn public confidence unless there is a transparent and trustworthy answer to what happens on the hundredth occasion."}]'::jsonb);

